}

/// Smart Battery status bitmask flags.
pub mod smart_battery_alerts {
    /// User requested return to home.
    pub const USER_REQ_GO_HOME: u32 = 1 << 0;
    /// Smart battery requested return to home.
    pub const SMART_REQ_GO_HOME: u32 = 1 << 1;
    /// User requested landing.
    pub const USER_REQ_LAND: u32 = 1 << 2;
    /// Smart battery requested landing.
    pub const SMART_REQ_LAND: u32 = 1 << 3;
    /// Main battery voltage low, initiating RTH.
    pub const MAIN_VOLTAGE_LOW_GO_HOME: u32 = 1 << 4;
    /// Main battery voltage low, initiating landing.
    pub const MAIN_VOLTAGE_LOW_LAND: u32 = 1 << 5;
    /// Voltage critically low, immediate landing required.
    pub const VOLTAGE_LOW_NEED_LAND: u32 = 1 << 6;
    /// Battery pack in dangerous condition.
    pub const BATTERY_DANGEROUS: u32 = 1 << 7;
    /// Battery temperature / voltage low alert.
    pub const BATTERY_TEMP_VOLTAGE_LOW: u32 = 1 << 8;
    /// Individual cell hardware or balance fault.
    pub const BATTERY_CELL_ERROR: u32 = 1 << 9;
    /// Communication failure with battery BMS controller.
    pub const BATTERY_COMMUNICATE_ERROR: u32 = 1 << 10;
    /// Battery output current power limit reached.
    pub const BATTERY_LIMIT_OUTPUT_MAX: u32 = 1 << 11;
    /// Battery not ready for flight.
    pub const BATTERY_NOT_READY: u32 = 1 << 12;
    /// First charge not full warning.
    pub const BATTERY_FIRST_CHARGE_NOT_FULL: u32 = 1 << 13;
}

/// Smart Battery Group telemetry packet (Record Type 22).
///
/// Encapsulates flight time countdowns, Return-to-Home thresholds, safe flight radius,
/// volume consumption, alert flags, and configured warning thresholds.
#[derive(Debug, Clone, PartialEq)]
pub struct SmartBatteryGroup {
    /// Remaining operational flight time in seconds.
    pub useful_time_secs: u16,
    /// Time required to return to home point in seconds.
    pub go_home_time_secs: u16,
    /// Time required for forced landing descent in seconds.
    pub land_time_secs: u16,
    /// Battery SOC threshold percentage triggering auto Return to Home.
    pub go_home_battery_percent: u16,
    /// Battery SOC threshold percentage triggering auto forced landing.
    pub land_battery_percent: u16,
    /// Maximum safe flight radius in meters.
    pub safe_fly_radius_m: f32,
    /// Cumulative volume / energy consumption in mAh.
    pub volume_consume_mah: f32,
    /// 32-bit smart battery alert flags bitmask.
    pub status_flags: u32,
    /// Return to Home execution status.
    pub go_home_status: SmartBatteryGoHomeStatus,
    /// Raw return-to-home status byte.
    pub raw_go_home_status: u8,
    /// Countdown in seconds before auto RTH begins.
    pub go_home_countdown: u8,
    /// Total battery pack operating voltage in Volts.
    pub voltage: f64,
    /// State of Charge percentage (0..=100%).
    pub battery_percent: u8,
    /// Low battery warning threshold percentage (0..=100%).
    pub low_warning_percent: u8,
    /// Whether low battery warning triggers Return to Home.
    pub low_warning_go_home: bool,
    /// Critical low battery warning threshold percentage (0..=100%).
    pub serious_low_warning_percent: u8,
    /// Whether critical low battery warning triggers auto landing.
    pub serious_low_warning_landing: bool,
}

impl SmartBatteryGroup {
    /// Parses a Record Type 22 payload.
    pub fn parse(payload: &[u8]) -> Result<Self> {
        if payload.len() < SMART_BATTERY_GROUP_MIN_LEN {
            return Err(FlightReaderError::TruncatedRecord {
                expected: SMART_BATTERY_GROUP_MIN_LEN,
                available: payload.len(),
            });
        }

        let useful_time_secs = LittleEndian::read_u16(&payload[0..2]);
        let go_home_time_secs = LittleEndian::read_u16(&payload[2..4]);
        let land_time_secs = LittleEndian::read_u16(&payload[4..6]);
        let go_home_battery_percent = LittleEndian::read_u16(&payload[6..8]);
        let land_battery_percent = LittleEndian::read_u16(&payload[8..10]);
        let safe_fly_radius_m = LittleEndian::read_f32(&payload[10..14]);
        let volume_consume_mah = LittleEndian::read_f32(&payload[14..18]);
        let status_flags = LittleEndian::read_u32(&payload[18..22]);
        let raw_go_home_status = payload[22];
        let go_home_countdown = payload[23];
        let voltage = LittleEndian::read_u16(&payload[24..26]) as f64 / 1000.0;
        let battery_percent = payload[26];

        let go_home_status = match raw_go_home_status {
            0 => {
                if go_home_countdown > 0 {
                    SmartBatteryGoHomeStatus::CountingDown
                } else {
                    SmartBatteryGoHomeStatus::Idle
                }
            }
            1 => SmartBatteryGoHomeStatus::Executed,
            2 => SmartBatteryGoHomeStatus::Cancelled,
            other => SmartBatteryGoHomeStatus::Other(other),
        };

        let warning_word = LittleEndian::read_u16(&payload[27..29]);
        let low_warning_percent = (warning_word & 0x7F) as u8;
        let low_warning_go_home = (warning_word & 0x80) != 0;
        let serious_low_warning_percent = ((warning_word >> 8) & 0x7F) as u8;
        let serious_low_warning_landing = (warning_word & 0x8000) != 0;

        Ok(Self {
            useful_time_secs,
            go_home_time_secs,
            land_time_secs,
            go_home_battery_percent,
            land_battery_percent,
            safe_fly_radius_m,
            volume_consume_mah,
            status_flags,
            go_home_status,
            raw_go_home_status,
            go_home_countdown,
            voltage,
            battery_percent,
            low_warning_percent,
            low_warning_go_home,
            serious_low_warning_percent,
            serious_low_warning_landing,
        })
    }

    /// Checks if a specific alert flag is active in `status_flags`.
    #[inline]
    pub fn has_alert(&self, flag: u32) -> bool {
        (self.status_flags & flag) != 0
    }
}

