/// Zero-allocation, fixed-capacity crash recovery record (Record Type 50).
///
/// Preserves component serial numbers, versions, and aircraft identifiers
/// emitted during sudden power-off or impact scenarios.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FlightRecordRecover {
    /// Drone model identifier code.
    pub drone_type: u8,
    /// Mobile application identifier code.
    pub app_type: u8,
    /// 3-part application version `[major, minor, patch]`.
    pub app_version: [u8; 3],
    /// Aircraft chassis serial number buffer.
    pub aircraft_serial: [u8; 16],
    /// Valid ASCII character count in `aircraft_serial`.
    pub aircraft_serial_len: u8,
    /// Aircraft user-assigned name buffer.
    pub aircraft_name: [u8; 32],
    /// Valid character count in `aircraft_name`.
    pub aircraft_name_len: u8,
    /// Camera payload serial number buffer.
    pub camera_serial: [u8; 16],
    /// Valid ASCII character count in `camera_serial`.
    pub camera_serial_len: u8,
    /// Remote controller serial number buffer.
    pub rc_serial: [u8; 16],
    /// Valid ASCII character count in `rc_serial`.
    pub rc_serial_len: u8,
    /// Battery pack serial number buffer.
    pub battery_serial: [u8; 16],
    /// Valid ASCII character count in `battery_serial`.
    pub battery_serial_len: u8,
    /// Gimbal hardware type code (if present).
    pub gimbal_type: Option<u8>,
    /// Whether modern (16-byte serials) or legacy (10-byte serials) format was detected.
    pub is_modern: bool,
}

impl FlightRecordRecover {
    /// Parses a Record Type 50 crash recovery payload.
    pub fn parse(payload: &[u8]) -> Result<Self> {
        if payload.len() < RECOVER_MIN_LEN {
            return Err(FlightReaderError::TruncatedRecord {
                expected: RECOVER_MIN_LEN,
                available: payload.len(),
            });
        }

        let drone_type = payload[0];
        let app_type = payload[1];
        let app_version = if payload.len() >= 5 {
            [payload[2], payload[3], payload[4]]
        } else {
            [0, 0, 0]
        };

        let is_modern = payload.len() >= 109;

        let mut aircraft_serial = [0u8; 16];
        let mut aircraft_serial_len = 0u8;
        let mut aircraft_name = [0u8; 32];
        let mut aircraft_name_len = 0u8;
        let mut camera_serial = [0u8; 16];
        let mut camera_serial_len = 0u8;
        let mut rc_serial = [0u8; 16];
        let mut rc_serial_len = 0u8;
        let mut battery_serial = [0u8; 16];
        let mut battery_serial_len = 0u8;

        if is_modern {
            // Modern layout (v12+)
            if payload.len() >= 21 {
                let slice = &payload[5..21.min(payload.len())];
                aircraft_serial_len = Self::sanitize_alphanumeric(slice, &mut aircraft_serial);
            }
            if payload.len() >= 53 {
                let slice = &payload[21..53.min(payload.len())];
                aircraft_name_len = Self::sanitize_printable(slice, &mut aircraft_name);
            }
            if payload.len() >= 77 {
                let slice = &payload[61..77.min(payload.len())];
                camera_serial_len = Self::sanitize_alphanumeric(slice, &mut camera_serial);
            }
            if payload.len() >= 93 {
                let slice = &payload[77..93.min(payload.len())];
                rc_serial_len = Self::sanitize_alphanumeric(slice, &mut rc_serial);
            }
            if payload.len() >= 109 {
                let slice = &payload[93..109.min(payload.len())];
                battery_serial_len = Self::sanitize_battery_serial(slice, &mut battery_serial);
            }
        } else {
            // Legacy layout
            if payload.len() >= 15 {
                let slice = &payload[5..15.min(payload.len())];
                aircraft_serial_len = Self::sanitize_alphanumeric(slice, &mut aircraft_serial);
            }
            if payload.len() >= 39 {
                let slice = &payload[15..39.min(payload.len())];
                aircraft_name_len = Self::sanitize_printable(slice, &mut aircraft_name);
            }
            if payload.len() >= 65 {
                let slice = &payload[55..65.min(payload.len())];
                camera_serial_len = Self::sanitize_alphanumeric(slice, &mut camera_serial);
            }
            if payload.len() >= 75 {
                let slice = &payload[65..75.min(payload.len())];
                rc_serial_len = Self::sanitize_alphanumeric(slice, &mut rc_serial);
            }
            if payload.len() >= 85 {
                let slice = &payload[75..85.min(payload.len())];
                battery_serial_len = Self::sanitize_battery_serial(slice, &mut battery_serial);
            }
        }

        let gimbal_type = if payload.len() >= 110 {
            Some(payload[109])
        } else {
            None
        };

        Ok(Self {
            drone_type,
            app_type,
            app_version,
            aircraft_serial,
            aircraft_serial_len,
            aircraft_name,
            aircraft_name_len,
            camera_serial,
            camera_serial_len,
            rc_serial,
            rc_serial_len,
            battery_serial,
            battery_serial_len,
            gimbal_type,
            is_modern,
        })
    }

    /// Filters and copies ASCII alphanumeric bytes into destination buffer.
    fn sanitize_alphanumeric(src: &[u8], dst: &mut [u8]) -> u8 {
        let mut count = 0usize;
        for &b in src {
            if count >= dst.len() {
                break;
            }
            if b.is_ascii_alphanumeric() {
                dst[count] = b;
                count += 1;
            } else if b == 0 {
                break;
            }
        }
        count as u8
    }

    /// Filters and copies printable ASCII bytes into destination buffer.
    fn sanitize_printable(src: &[u8], dst: &mut [u8]) -> u8 {
        let mut count = 0usize;
        for &b in src {
            if count >= dst.len() {
                break;
            }
            if b >= 0x20 && b <= 0x7E {
                dst[count] = b;
                count += 1;
            } else if b == 0 {
                break;
            }
        }
        count as u8
    }

    /// Sanitizes battery serial number, filtering out `"0000000000"`.
    fn sanitize_battery_serial(src: &[u8], dst: &mut [u8]) -> u8 {
        let len = Self::sanitize_alphanumeric(src, dst);
        let slice = &dst[..len as usize];
        if slice == b"0000000000" || slice.iter().all(|&b| b == b'0') {
            0
        } else {
            len
        }
    }

    /// Returns aircraft chassis serial number as a borrowed string slice.
    pub fn aircraft_serial_str(&self) -> &str {
        std::str::from_utf8(&self.aircraft_serial[..self.aircraft_serial_len as usize])
            .unwrap_or("")
    }

    /// Returns aircraft name as a borrowed string slice.
    pub fn aircraft_name_str(&self) -> &str {
        std::str::from_utf8(&self.aircraft_name[..self.aircraft_name_len as usize])
            .unwrap_or("")
    }

    /// Returns camera serial number as a borrowed string slice.
    pub fn camera_serial_str(&self) -> &str {
        std::str::from_utf8(&self.camera_serial[..self.camera_serial_len as usize])
            .unwrap_or("")
    }

    /// Returns remote controller serial number as a borrowed string slice.
    pub fn rc_serial_str(&self) -> &str {
        std::str::from_utf8(&self.rc_serial[..self.rc_serial_len as usize])
            .unwrap_or("")
    }

    /// Returns battery serial number as a borrowed string slice.
    pub fn battery_serial_str(&self) -> &str {
        std::str::from_utf8(&self.battery_serial[..self.battery_serial_len as usize])
            .unwrap_or("")
    }

    /// Returns formatted application version string e.g. `"4.3.2"`.
    pub fn app_version_string(&self) -> String {
        format!("{}.{}.{}", self.app_version[0], self.app_version[1], self.app_version[2])
    }
}
